<?php
namespace App\Http\Controllers;use App\Models\{EmployeeTrip,TripExpense};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class TripExpenseController extends Controller{public function index(EmployeeTrip $trip){$trip->load('employee');$expenses=$trip->expenses()->latest('expense_date')->paginate(10);return view('trips.expenses',compact('trip','expenses'));}public function store(Request $r,EmployeeTrip $trip){$trip->expenses()->create($this->data($r)+['employee_trip_id'=>$trip->id]);$this->sync($trip);return back()->with('success','Expense added successfully.');}public function update(Request $r,EmployeeTrip $trip,TripExpense $expense){abort_unless($expense->employee_trip_id===$trip->id,404);$expense->update($this->data($r,$expense));$this->sync($trip);return back()->with('success','Expense updated successfully.');}public function status(Request $r,EmployeeTrip $trip,TripExpense $expense){abort_unless($expense->employee_trip_id===$trip->id,404);$expense->update($r->validate(['status'=>'required|in:Pending,Approved,Paid,Rejected']));$this->sync($trip);return back()->with('success','Reimbursement status updated.');}public function receipt(EmployeeTrip $trip,TripExpense $expense){abort_unless($expense->employee_trip_id===$trip->id&&$expense->receipt_path&&Storage::disk('public')->exists($expense->receipt_path),404);return Storage::disk('public')->response($expense->receipt_path);}public function destroy(EmployeeTrip $trip,TripExpense $expense){abort_unless($expense->employee_trip_id===$trip->id,404);if($expense->receipt_path)Storage::disk('public')->delete($expense->receipt_path);$expense->delete();$this->sync($trip);return back()->with('success','Expense deleted.');}private function data(Request $r,?TripExpense $expense=null){$d=$r->validate(['expense_type'=>'required|in:Transportation,Accommodation,Meals,Communication,Registration,Other','expense_date'=>'required|date','amount'=>'required|numeric|min:0.01','description'=>'nullable|string|max:2000','receipt'=>'nullable|file|mimes:pdf,jpg,jpeg,png|max:5120','reimbursable'=>'nullable|boolean']);unset($d['receipt']);$d['currency']='BDT';$d['reimbursable']=$r->boolean('reimbursable');if($r->hasFile('receipt')){if($expense?->receipt_path)Storage::disk('public')->delete($expense->receipt_path);$d['receipt_path']=$r->file('receipt')->store('trip-expenses','public');}return $d;}private function sync(EmployeeTrip $trip){$trip->update(['expense_amount'=>$trip->expenses()->sum('amount'),'expense_status'=>$trip->expenses()->exists()?($trip->expenses()->where('status','Pending')->exists()?'Pending':($trip->expenses()->where('status','Rejected')->exists()?'Rejected':'Approved')):null]);}}
